/** Cache-Control for content-hashed assets: safe to cache forever. */
const IMMUTABLE = 'public, max-age=31536000, immutable'

/** File name read by Cloudflare Pages and Netlify. */
export const HEADERS_FILENAME = '_headers'

/**
 * Render a `_headers` file (Cloudflare Pages / Netlify format) that makes
 * federated updates reliable on a plain refresh: the manifests revalidate on
 * every load (so a redeployed remote is picked up), while content-hashed
 * bundles cache immutably (new content means a new file name).
 */
export function renderHeaders(): string {
  return [
    '# Generated by native-federation-vite.',
    '# Manifests revalidate each load; content-hashed bundles cache immutably.',
    '/remoteEntry.json',
    '  Cache-Control: no-cache',
    '/importmap.json',
    '  Cache-Control: no-cache',
    '/*.js',
    `  Cache-Control: ${IMMUTABLE}`,
    '/*.css',
    `  Cache-Control: ${IMMUTABLE}`,
    '/assets/*',
    `  Cache-Control: ${IMMUTABLE}`,
    ''
  ].join('\n')
}
